"""``status`` -- activate/deactivate datasets in the working set, by index."""

from __future__ import annotations

import click

from .._apply import is_active, parse_indices, set_active


@click.command("status")
@click.option("--activate", "-a", "activate_spec", default=None,
    help="Index spec to activate: '1', '0,2,5', '1:6:2', or ':' for all.")
@click.option("--deactivate", "-d", "deactivate_spec", default=None,
    help="Index spec to deactivate; same forms as --activate.")
@click.pass_context
def command(ctx, activate_spec, deactivate_spec) -> None:
  """Activate/deactivate datasets in the working set (by index).

  Deactivated datasets are skipped by transform commands (fft, magsq, ...)
  and by the terminal commands (info, plot, save). With neither option,
  prints the current active/inactive status of every dataset.
  """
  datasets = ctx.obj.datasets
  if activate_spec is not None:
    for i in parse_indices(activate_spec, len(datasets)):
      set_active(datasets[i], True)
    # end
  # end
  if deactivate_spec is not None:
    for i in parse_indices(deactivate_spec, len(datasets)):
      set_active(datasets[i], False)
    # end
  # end
  if activate_spec is None and deactivate_spec is None:
    for i, d in enumerate(datasets):
      state = "active" if is_active(d) else "inactive"
      click.echo(f"[{i}] {state}  tag={d.tag!r}")
# end
    # end
  # end
## gk_fluxsurf.py
"""``gk_fluxsurf`` -- extract a 2-D theta-phi flux surface from 3-D data."""

from __future__ import annotations

import inspect

import click

import postgkyl as pg

from .._apply import active_datasets, apply
from .._options import label_option, tag_option, use_option


def _default(function, name: str):
  """Derive CLI defaults from the authoritative operation signature."""
  return inspect.signature(function).parameters[name].default
# end


@click.command("gk_fluxsurf")
@click.option("--mapc2p", "-m",
    default=_default(pg.operations.gyrokinetics.resolve_geometry, "mapc2p"),
    type=click.STRING,
    help="Use a modal mapc2p file as the geometry source instead of the default "
         "nodes file.")
@click.option("--nodes", "-n", "nodes_file",
    default=_default(pg.operations.gyrokinetics.resolve_geometry, "nodes_file"),
    type=click.STRING,
    help="Path to a nodal geometry file, overriding the default lookup.")
@click.option("--x-idx", "-x", type=int,
    default=_default(pg.operations.gyrokinetics.resolve_flux_surface_grid, "x_idx"),
    help="Cell index in the radial (x) direction representing the flux surface.")
@click.option("--nphi", type=int,
    default=_default(pg.operations.gyrokinetics.resolve_flux_surface_grid, "nphi"),
    help="Number of toroidal angle (phi) slices.")
@click.option("--nz-interp", type=int,
    default=_default(pg.operations.gyrokinetics.resolve_flux_surface_grid, "nz_interp"),
    help="Parallel (z) up-sampling factor used to smooth the projected 3-D surfaces.")
@use_option
@tag_option(default="fluxsurf")
@label_option()
@click.pass_context
def command(ctx, mapc2p, nodes_file, x_idx, nphi, nz_interp, use, tag, label) -> None:
  """Gyrokinetics: extract a 2-D theta-phi flux surface.

  Extracts data along a specific radial flux surface (constant x) for 3-D
  field-aligned data, by performing a binormal projection over a scan of
  toroidal angles (phi), creating a 2-D grid of phi vs z (where z maps
  along the poloidal/theta direction).

  The geometry is found the same way as ``gk_rz``: from the prefix of the
  first matching dataset's source file, preferring the pointwise
  '<prefix>-geo_int_nodes.gkyl', falling back to the modal
  '<prefix>-geo_int_mapc2p.gkyl'.
  """
  targets = [d for d in active_datasets(ctx) if use is None or d.tag == use]
  if not targets:
    return
  # end

  gk_ops = pg.operations.gyrokinetics
  geo = gk_ops.resolve_geometry(
      targets[0].file_name, mapc2p=mapc2p, nodes_file=nodes_file)
  fs_grid = gk_ops.resolve_flux_surface_grid(
      targets[0], geo, x_idx=x_idx, nphi=nphi, nz_interp=nz_interp)

  apply(ctx, lambda d: gk_ops.extract_flux_surface(
      d, fs_grid, tag=tag, label=label), use=use)
# end
## gk_rz.py
"""``gk_rz`` -- interpolate DG data and map it onto the R-Z plane."""

from __future__ import annotations

import inspect

import click

import postgkyl as pg

from .._apply import active_datasets, apply
from .._options import label_option, tag_option, use_option


def _default(name: str):
  """Derive CLI defaults from the authoritative operation signature."""
  return inspect.signature(pg.gk_rz).parameters[name].default
# end


@click.command("gk_rz")
@click.option("--mapc2p", "-m", default=_default("mapc2p"), type=click.STRING,
    help="Use a modal mapc2p file as the geometry source instead of the default "
         "nodes file; pass '' to look up '<prefix>-geo_int_mapc2p.gkyl' from the "
         "first processed dataset's prefix.")
@click.option("--nodes", "-n", "nodes_file", default=_default("nodes_file"), type=click.STRING,
    help="Path to a nodal geometry file, overriding the default "
         "'<prefix>-geo_int_nodes.gkyl' lookup.")
@click.option("--z-axis", "-z", type=float, default=_default("z_axis"),
    help="Vertical position of the magnetic axis (m), added to the geometry Z. "
         "mapc2p files store Z relative to the axis; pass Z_axis from the "
         "simulation input file to plot in machine coordinates.")
@click.option("--phi-tor", "-p", type=float, default=_default("phi_tor"),
    help="Toroidal angle (radians) of the poloidal plane to project 3-D data onto.")
@click.option("--nz-interp", type=int, default=_default("nz_interp"),
    help="Parallel (z) up-sampling factor used to smooth the projected 3-D surfaces.")
@use_option
@tag_option(default="rz")
@label_option()
@click.pass_context
def command(ctx, mapc2p, nodes_file, z_axis, phi_tor, nz_interp, use, tag,
    label) -> None:
  """Gyrokinetics: interpolate DG dataset(s) and map them to the R-Z plane.

  Assumes DG data (not yet interpolated) has been loaded onto the working
  set by a preceding command.

  The geometry is found from the prefix of the first matching dataset's
  source file: the pointwise '<prefix>-geo_int_nodes.gkyl' is preferred
  (exact node coordinates, robust at coarse z resolution), falling back to
  the modal '<prefix>-geo_int_mapc2p.gkyl'. Use '-n path' to point at a
  specific nodes file, '-m path' at a specific mapc2p file, or "-m ''" to
  force the default mapc2p lookup.

  For 3-D (field-aligned) data the field is reconstructed on the poloidal
  plane at toroidal angle --phi-tor (default 0) by interpolating along the
  binormal direction, up-sampled in z (--nz-interp) for smooth surfaces.
  """
  targets = [d for d in active_datasets(ctx) if use is None or d.tag == use]
  if not targets:
    return
  # end

  gk_ops = pg.operations.gyrokinetics
  geo = gk_ops.resolve_geometry(
      targets[0].file_name, mapc2p=mapc2p, nodes_file=nodes_file)
  projection = gk_ops.resolve_rz_projection(
      targets[0], geo, z_axis=z_axis, nz_interp=nz_interp)

  apply(ctx, lambda d: gk_ops.map_to_rz(
      d, projection, phi_tor=phi_tor, tag=tag, label=label), use=use)
# end
